import { readFile, writeFile } from 'node:fs/promises';

// Keep index.html self-contained so it also runs over file://, without a server.
const root = new URL('../', import.meta.url);
const read = path => readFile(new URL(path, root), 'utf8');
const css = await read('src/style.css');
const game = (await read('src/game.js')).replace(/^export /gm, '');
const app = (await read('src/main.js')).replace(/^import .*;\r?\n/gm, '');
const script = `${game}\n${app}`.replace(/<\/script/gi, '<\\/script');
await writeFile(new URL('index.html', root), `<!doctype html>
<!-- Generated by scripts/build-page.mjs. Edit src/ files, then run npm run build:page. -->
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <meta name="theme-color" content="#f6f5ef" />
    <meta name="description" content="A little wordplay for your day. Play Hangman with helpful clues and three difficulty levels." />
    <title>Hangman — A little wordplay</title>
    <style>${css}</style>
  </head>
  <body>
    <div id="app"></div>
    <script>
(() => {
${script}
})();
    </script>
  </body>
</html>
`);
console.log('Created standalone index.html (no server or installation required).');
